"""Writes RELEASES.md: each app's latest release (version, date, download, size) and its release history.

GitHub marks one release "Latest" for the whole repo; this page gives each app its own. Releases are
tagged <project>/vX.Y.Z (projects.py); the attached .zab comes from release.yml. Run by
.github/workflows/releases-md.yml after each release, or locally (needs `gh`):

  python3 .github/scripts/releases.py [releases.json]   (a saved `gh api repos/{owner}/{repo}/releases` list, for testing)
"""
import json
import re
import subprocess
import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
PROJECTS = tomllib.loads((ROOT / "mise.toml").read_text())["monorepo"]["config_roots"]
TAG = re.compile(r"(.+)/v(\d+\.\d+\.\d+(?:[-+][\w.]+)?)")
SUMMARY_LEN = 220


def releases(path=None):
    if path:
        return json.loads(Path(path).read_text())
    out = subprocess.check_output(["gh", "api", "--paginate", "--slurp", "repos/{owner}/{repo}/releases"], cwd=ROOT, text=True)
    return [r for page in json.loads(out) for r in page]


def size(n):
    return f"{n / 1e6:.1f} MB" if n >= 1e6 else f"{round(n / 1e3)} KB"


def summary(body):
    """The release notes' first paragraph, as one line."""
    para = next((p for p in re.split(r"\n\s*\n", body or "") if p.strip() and not p.lstrip().startswith("#")), "")
    text = " ".join(para.split())
    return text if len(text) <= SUMMARY_LEN else text[:SUMMARY_LEN].rsplit(" ", 1)[0] + " …"


def render(all_releases):
    by_project = {}
    for r in all_releases:
        m = TAG.fullmatch(r["tag_name"])
        if r["draft"] or not m or m.group(1) not in PROJECTS:
            continue
        by_project.setdefault(m.group(1), []).append({**r, "version": m.group(2), "date": r["published_at"][:10]})
    lines = [
        "# Releases",
        "",
        "<!-- Generated by .github/scripts/releases.py after each release; don't edit by hand. -->",
        "",
        "The latest version of each app. Each release has one `.zab` with every supported watch. Install it with",
        "[Gadgetbridge](guide/gadgetbridge.md): open the file with Gadgetbridge on your phone while the watch is connected.",
        "",
        "| App | Version | Released | Download | Watches |",
        "|---|---|---|---|---|",
    ]
    ordered = [p for p in PROJECTS if p in by_project]
    for p in ordered:
        rs = sorted(by_project[p], key=lambda r: r["published_at"], reverse=True)
        by_project[p] = rs
        latest = rs[0]
        name = json.loads((ROOT / p / "app.json").read_text())["app"]["appName"]
        zab = next((a for a in latest["assets"] if a["name"].endswith(".zab")), None)
        download = f"[`{zab['name']}`]({zab['browser_download_url']}) ({size(zab['size'])})" if zab else "building…"
        lines.append(f"| [{name}]({p}/README.md) | [{latest['version']}]({latest['html_url']}) | {latest['date']} "
                     f"| {download} | [list]({p}/README.md#devices) |")
    for p in ordered:
        name = json.loads((ROOT / p / "app.json").read_text())["app"]["appName"]
        lines += ["", f"## {name}", ""]
        for r in by_project[p]:
            text = summary(r["body"])
            lines.append(f"- **[{r['version']}]({r['html_url']})** ({r['date']})" + (f": {text}" if text else ""))
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    assert size(3910257) == "3.9 MB" and size(80183) == "80 KB"
    assert summary("## Notes\n\nFirst  line\nsecond.\n\nMore.") == "First line second."
    out = render(releases(sys.argv[1] if len(sys.argv) > 1 else None))
    (ROOT / "RELEASES.md").write_text(out)
    print(out)
